-- One read-only SELECT per line, executed inside the checker's READ ONLY transaction.
SELECT rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolbypassrls FROM pg_roles WHERE rolname IN (current_user,'anon','authenticated','authenticator','service_role');
SELECT member.rolname AS member,parent.rolname AS inherited_role,m.admin_option FROM pg_auth_members m JOIN pg_roles member ON member.oid=m.member JOIN pg_roles parent ON parent.oid=m.roleid WHERE member.rolname IN (current_user,'anon','authenticated','authenticator') ORDER BY 1,2;
SELECT n.nspname,c.relname,c.relkind,pg_get_userbyid(c.relowner) AS owner,c.relrowsecurity,c.relforcerowsecurity,CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END AS grantee,a.privilege_type,a.is_grantable FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(COALESCE(c.relacl,acldefault(CASE WHEN c.relkind='S' THEN 's'::"char" ELSE 'r'::"char" END,c.relowner))) a WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','S') ORDER BY 2,7,8;
SELECT pg_get_userbyid(d.defaclrole) AS creator,COALESCE(n.nspname,'GLOBAL') AS schema,d.defaclobjtype,CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END AS grantee,a.privilege_type,a.is_grantable FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace CROSS JOIN LATERAL aclexplode(d.defaclacl) a ORDER BY 1,2,3,4,5;
SELECT schemaname,tablename,policyname,permissive,roles,cmd,qual IS NOT NULL AS has_using,with_check IS NOT NULL AS has_check FROM pg_policies WHERE schemaname='public' ORDER BY tablename,policyname;
SELECT nspname,CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END AS grantee,a.privilege_type FROM pg_namespace CROSS JOIN LATERAL aclexplode(COALESCE(nspacl,acldefault('n',nspowner))) a WHERE nspname IN ('public','extensions','auth','storage') ORDER BY 1,2,3;
SELECT COALESCE(r.rolname,'ALL') AS role,COALESCE(d.datname,'ALL') AS database,s.setting FROM pg_db_role_setting s0 LEFT JOIN pg_roles r ON r.oid=s0.setrole LEFT JOIN pg_database d ON d.oid=s0.setdatabase CROSS JOIN LATERAL unnest(s0.setconfig) s(setting) WHERE s.setting LIKE 'pgrst.db_schemas=%' OR s.setting LIKE 'pgrst.db_extra_search_path=%';
SELECT name,setting FROM pg_settings WHERE name IN ('pgrst.db_schemas','pgrst.db_extra_search_path');
SELECT current_setting('pgrst.db_schemas',true) AS session_exposed_schemas,current_setting('pgrst.db_extra_search_path',true) AS session_extra_search_path;
SELECT n.nspname,p.proname,p.prosecdef,has_function_privilege('anon',p.oid,'EXECUTE') AS anon_execute,has_function_privilege('authenticated',p.oid,'EXECUTE') AS authenticated_execute FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' ORDER BY p.proname;
SELECT pg_describe_object(d.classid,d.objid,d.objsubid) AS dependent,pg_describe_object(d.refclassid,d.refobjid,d.refobjsubid) AS referenced,d.deptype FROM pg_depend d JOIN pg_class c ON c.oid=d.refobjid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE d.refclassid='pg_class'::regclass AND n.nspname='public' AND c.relname IN ('users','country','phone_prefix','flyway_schema_history') ORDER BY 2,1;
SELECT a.name,a.version,a.superuser,a.trusted,a.relocatable,a.schema,a.requires FROM pg_available_extension_versions a WHERE a.name='btree_gist';
SELECT e.extname,n.nspname AS schema,pg_get_userbyid(e.extowner) AS owner FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname='btree_gist';
SELECT rolname,has_table_privilege(rolname,'public.users','SELECT') AS read_users,has_table_privilege(rolname,'public.users','UPDATE') AS update_users,has_table_privilege(rolname,'public.flyway_schema_history','UPDATE') AS update_history FROM pg_roles WHERE rolname IN (current_user,'anon','authenticated');
